namespace sv_beadfb54c89e43cfbbc1b528c67968d3.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service holding the currently selected warehouse for this circuit.
/// Each user connection gets its own instance, so selections are independent.
/// </summary>
public class WarehouseState
{
    private string _currentWarehouseId = "wh-1";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A — East" },
        new() { Id = "wh-2", Name = "Warehouse B — West" },
        new() { Id = "wh-3", Name = "Warehouse C — Central" },
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_beadfb54c89e43cfbbc1b528c67968d3.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Polling is reference-counted: starts when the first component subscribes,
/// stops when the last unsubscribes.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants to receive alert updates.
    /// Starts polling if this is the first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs updates.
    /// Stops polling when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Forces an immediate refresh (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        _currentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Do an immediate first fetch
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer!.WaitForNextTickAsync(ct))
                    break;
                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        CancelPolling();
    }
}

