@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-5">
                    @(Services.WarehouseState.AvailableWarehouses
                        .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
                        ?? "Unknown")
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text">
                    <span class="badge bg-danger fs-4">@AlertService.CurrentAlertCount</span>
                    <span class="ms-2 text-muted">items below minimum level</span>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text text-success">
                    <span class="bi bi-circle-fill me-1"></span> Active — refreshing every 10s
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when this page is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

